import * as T from 'three/tsl';
export function pathMediaNode({load,trace,ray},u,enabled=true){
 const id=T.Fn(([triangle])=>enabled?load(u.transport.x.add(triangle.mul(2)).add(1)).w:T.float(0)).setLayout({name:'hbMediumID',type:'float',inputs:[{name:'id',type:'float'}]});
 const value=T.Fn(([triangle,p,view])=>{const a=ray.field(triangle,p,view,4);return T.vec4(a.w.greaterThan(0).select(a.rgb.max(.000001).log().negate().div(a.w.max(.000001)),T.vec3(0)),ray.field(triangle,p,view,0).w);}).setLayout({name:'hbMediumValue',type:'vec4',inputs:[{name:'id',type:'float'},{name:'point',type:'vec3'},{name:'view',type:'vec3'}]});
 const seed=(start,direction,shadowRay=false)=>{
  if(!enabled)return {ids:{element:()=>T.float(0)},media:{element:()=>T.vec4(0,0,0,1)},count:T.int(0).toVar()};
  const ids=T.array(Array.from({length:16},()=>T.float(0))).toVar(),media=T.array(Array.from({length:16},()=>T.vec4(0))).toVar(),count=T.int(0).toVar();
  T.If(u.pathOptions.y.greaterThan(.5),()=>{const seen=T.array(Array.from({length:64},()=>T.float(0))).toVar(),seenCount=T.int(0).toVar(),origin=start.toVar(),complete=T.bool(false).toVar();
   T.Loop({start:0,end:T.int(u.transport.w).min(64),type:'int',name:'mediumScan'},()=>{const hit=trace(origin,direction.negate(),u.geometry.y).toVar();T.If(hit.w.lessThan(.5),()=>{count.assign(-1);T.Break();});T.If(hit.z.lessThan(.5),()=>{complete.assign(true);T.Break();});const p=origin.sub(direction.mul(hit.x)),volume=id(hit.y).toVar();T.If(volume.greaterThan(0).and(shadowRay?load(u.transport.x.add(hit.y.mul(2)).add(1)).x.greaterThan(.5):T.bool(true)),()=>{const known=T.bool(false).toVar();T.Loop({start:0,end:seenCount,type:'int',name:'mediumSeen'},({mediumSeen:j})=>{T.If(seen.element(j).equal(volume),()=>{known.assign(true);});});T.If(known.not(),()=>{seen.element(seenCount).assign(volume);seenCount.addAssign(1);T.If(ray.geometric(hit.y).dot(direction.negate()).greaterThan(0),()=>{T.If(count.equal(16),()=>{count.assign(-1);T.Break();});T.Loop({start:15,end:0,condition:'>',update:'--',type:'int',name:'mediumInsert'},({mediumInsert:j})=>{T.If(j.lessThanEqual(count),()=>{ids.element(j).assign(ids.element(j.sub(1)));media.element(j).assign(media.element(j.sub(1)));});});ids.element(0).assign(volume);media.element(0).assign(value(hit.y,p,direction));count.addAssign(1);});});});origin.assign(p.sub(direction.mul(u.geometryLimits.y.mul(2))));});T.If(complete.not(),()=>{count.assign(-1);});
  });return {ids,media,count};
 };
 const change=(state,volume,v,front)=>{if(!enabled)return;const {ids,media,count}=state;T.If(front,()=>{T.If(count.equal(16),()=>{count.assign(-1);}).Else(()=>{ids.element(count.clamp(0,15)).assign(volume);media.element(count.clamp(0,15)).assign(v);count.addAssign(1);});}).Else(()=>{const found=T.int(-1).toVar();T.Loop({start:0,end:count,type:'int',name:'mediumFind'},({mediumFind:j})=>{T.If(ids.element(j).equal(volume),()=>{found.assign(j);});});T.If(found.lessThan(0),()=>{count.assign(-1);}).Else(()=>{T.Loop({start:0,end:15,type:'int',name:'mediumRemove'},({mediumRemove:j})=>{T.If(j.greaterThanEqual(found).and(j.lessThan(count.sub(1))),()=>{ids.element(j).assign(ids.element(j.add(1)));media.element(j).assign(media.element(j.add(1)));});});count.subAssign(1);});});};
 return {id,value,seed,change};
}
